(()=>{const stream=document.querySelector('#timeline-stream');if(!stream)return;const events=[...stream.querySelectorAll('.timeline-event')],buttons=[...document.querySelectorAll('.timeline-toolbar button')],search=document.querySelector('#timeline-search');let category='';const apply=()=>{const q=search.value.toLocaleLowerCase('tr').trim();events.forEach(e=>e.classList.toggle('filtered',!!category&&e.dataset.category!==category||!!q&&!e.dataset.search.includes(q)))};buttons.forEach(b=>b.onclick=()=>{category=b.dataset.category||'';buttons.forEach(x=>x.classList.toggle('active',x===b));apply()});search.addEventListener('input',apply);events.forEach(e=>{const b=e.querySelector('.timeline-node'),d=e.querySelector('.timeline-detail');b.onclick=()=>{const open=b.getAttribute('aria-expanded')==='true';b.setAttribute('aria-expanded',String(!open));d.classList.toggle('active',!open)}})})();
